from pathlib import Path
import json,re,hashlib,subprocess,html,collections
out=Path(__file__).resolve().parent;tree=Path('/workspace/orm-adapted');main=Path('/workspace/orm-main')
read=lambda p:json.loads(p.read_text())
rows=[json.loads(s) for s in (out/'census.jsonl').read_text().splitlines()];probe=[json.loads(s) for s in (out/'probe.jsonl').read_text().splitlines()];assert rows==probe
assert rows[0]['latent_mode']=='full' and not rows[0]['checker_rejected']
c=read(out/'checker.json');assert c['typescript']=='6.0.3' and not c['diagnostics']
units={u['where']:u for r in rows for u in r.get('units',[])}
selected=[dict(unit_name=units[f['unit']].get('name'),finding=f) for r in rows for f in r.get('findings',[]) if re.match(r'^overload \d+ of \S+ parameter\b',f['reason'])]
assert len(selected)==8
(out/'overload-parameters.json').write_text(json.dumps(selected,indent=2)+'\n')
traces=[];context=''
for line in (out/'probe.log').read_text().splitlines():
 if line.startswith('PARAMETER overload'):context=line
 if line.startswith('HOLDSANY branch='):
  m=re.match(r'HOLDSANY branch=(\w+) depth=(\d+) flags=(\d+) path=(.*)',line);branch,depth,flags,path=m.groups()
  path=[json.loads(s) for s in re.findall(r'"(?:[^"\\]|\\.)*"',path)]
  traces.append(dict(parameter=context,branch=branch,depth=int(depth),flags=int(flags),path=path))
assert len(traces)==12 and all(t['branch']=='bound' and t['depth']==32 and len(t['path'])==33 and not t['flags']&1 for t in traces)
(out/'depth-traces.json').write_text(json.dumps(traces,indent=2)+'\n')
manifest=read(out.parent/'overload-results-main/adapted-source-hashes.json')
assert all(hashlib.sha256((tree/p).read_bytes()).hexdigest()==sha for p,sha in manifest.items())
assert all(manifest[k]==v for k,v in c['sourceHashes'].items())
(out/'adapted-source-hashes.json').write_text(json.dumps(manifest,indent=2)+'\n')
for name in ['overload_callback_use.go','census_small.go','overload_callback_use_test.go']:
 (out/(name+'.txt')).write_bytes((main/'internal/lower'/name).read_bytes())
mainsha=subprocess.check_output(['git','-C',str(main),'rev-parse','HEAD'],text=True).strip();assert mainsha==c['main']=='219dbb6e7e20ea99d3e5d4b61c0cb14102dc9205'
assert not subprocess.check_output(['git','-C',str(main),'status','--porcelain','--untracked-files=no'])
prov=dict(main=mainsha,report_parent='7d73b282da946b85a73d3e77b2aea0e3f891f30d',typescript=c['typescript'],adapted_source_hashes_match_previous_census=True,stock_binary_sha256=hashlib.sha256(Path('/workspace/orm-build-main/entry-census').read_bytes()).hexdigest(),probe_binary_sha256=hashlib.sha256(Path('/workspace/dao-probe/entry-census').read_bytes()).hexdigest(),stock_overlay=read(Path('/workspace/orm-build-main/entry-overlay/overlay.json')),stock_and_instrumented_census_identical=True)
(out/'provenance.json').write_text(json.dumps(prov,indent=2)+'\n')
def short(w):return w.removeprefix(str(tree)+'/')
def esc(x):return html.escape(str(x),quote=False).replace('|','\\|').replace('\n','<br>')
def table(head,rows):return '\n'.join(['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |',*['| '+' | '.join(esc(v) for v in r)+' |' for r in rows]])+'\n'
lines=['# Debug assertion overloads — task 68x1t2y','',f'Measured main `{mainsha}` and exactly the same adapted tree as `overload-results-main` (all 747 file hashes verified). The census uses the existing own-tree entry overlay and binary, unsplit with no shard selectors. This directory contains evidence and scratch instrumentation only.','','## 1. Single-file full-mode census','','`LATENT_FULL=1`, `LATENT_ONLY_FILE=/workspace/orm-adapted/src/compiler/transformers/destructuring.ts`, `LATENT_ASSERT_NO_OUTPUT=1`; entry root remains adapted `src/tsc/tsc.ts`. The stock run has zero checker diagnostics and 26 measured units. It records **8 overload-parameter observations**, at **3 unique declaration/reason sites**. Every matching observation follows; locations are in the frozen adapted tree.','',table(['Unit','Unit location','Finding location','Exact reason'],[[e['unit_name'],short(e['finding']['unit']),short(e['finding']['where']),e['finding']['reason']] for e in selected]),'','Full mode includes the nested `emitBindingOrAssignment` unit at :318 as well as its enclosing `flattenDestructuringBinding` unit at :244. The two assertNode observations are the same :319 call reached in those two unit attempts. The other assertNode call at :185 is included in the checker evidence for completeness; the full-mode census does not report an overload-parameter finding for it.','','## 2. Stock TypeScript 6.0.3 checker','','The stock program uses the same strict options and adapted entry root, plus main’s exact bundled @types/node 25.3.3 declarations, as the census loader supplies. It has **zero diagnostics**. No adapted source is changed. `checker.json` retains every resolved declaration, instantiated signature, implementation and source hash. Overload indices are one-based among signature declarations, excluding the implementation.','','The requested `assertNode` “around :244” belongs to `flattenDestructuringBinding` at :244: its nested `emitBindingOrAssignment` starts at :318 and calls the assertion at :319.']
requested=[next(x for x in c['calls'] if x['location'].endswith(':601:5')),next(x for x in c['calls'] if x['location'].endswith(':319:9'))]
for call in requested:
 lines+=['','### '+call['function']+' at '+call['location'],'','```ts',call['call'],'```','',table(['Fact','Checker evidence'],[['Argument expression',call['argument']['expression']],['Argument declared type',call['argument']['declaredType']],['Argument flow type at call',call['argument']['flowType']],['test expression',call['test']['expression']],['test type',call['test']['type']],['Predicate target',call['test']['signatures'][0]['predicate']['targetType']],['Resolved overload',str(call['resolved']['index'])+' @ '+call['resolved']['location']],['Implementation test parameter',call['implementation']['testParameterText']],['Implementation test parameter type',call['implementation']['testParameterType']]]),'','Resolved overload declaration:','','```ts',call['resolved']['declaration'],'```','','Instantiated resolved signature:','','```ts',call['resolved']['instantiatedSignature'],'```']
lines+=['','The :185 call is `Debug.assertNode(target, createAssignmentCallback ? isIdentifier : isExpression)`: target is also declared `BindingOrAssignmentElementTarget`; its test expression has type `(node: Node) => node is Expression`, target `Expression`, and resolves assertNode overload 1.','','The checker-resolved assertEachNode overload is **2**, whereas the refusal names **4**. Lowering’s `censusOverloads` walks **every** overload declaration, stopping at the first unserved declaration, rather than checking only the signature chosen for this call. The probe records overloads 1–3 passing the body-use exception with rigid T, then overload 4 failing with the concrete `BindingOrAssignmentElement` callback parameter.','','## 3. Exact refusal branch and reachable any','','**Both requested calls fail because `overloadCallbackHoldsAny` reaches its `depth >= 32` bound. No TypeFlagsAny branch triggers; the bound also stops caller-type recovery before any flow-type equality test.**','','The unmodified and instrumented full-census streams are **exactly equal**, including the relation trailer. The scratch instrumentation preserves branch order, short-circuiting, seen-set use and return values. It adds complete depth paths and parameter/door logs. All 12 true walker events (two assertNode unit attempts × two guards, four assertEachNode unit attempts × two guards) are bound events at depth 32, with non-any flags. `depth-traces.json` retains all events; `probe.log` retains their order and callback gate outcomes.','','The outer emitter in `census_small.go:228` refuses only if **both** `censusRelated(given, takes)` and `overloadCallbackUse(...)` are false. The direct relation is false for the narrow predicate callback against `((node: Node) => boolean) | undefined`. The fallback fails as follows:','','- assertEachNode: `overloadCallbackElement` reaches its admitted-array guard (`element == nil || overloadCallbackHoldsAny(admitted, ...)`, original :329). The index element exists, but the admitted `readonly BindingOrAssignmentElement[] | undefined` hits the bound. Recovery returns the existing flow type **Node**, before checking `flow == concrete(own)` or its nonnullable variant. `overloadCallbackCall` then checks promised `BindingOrAssignmentElement`; its holds-any guard again hits the bound, and the relation operand is short-circuited.','- assertNode: `overloadCallbackArgument` reaches the admitted `BindingOrAssignmentElementTarget | undefined` guard (original :246), hits the bound and returns flow type **Node**, before the flow-type match. `overloadCallbackCall` then checks the promised nonnullable target union, hits the bound again, and short-circuits the relation.','','Thus the failure is neither a flow-type mismatch nor a discovered non-library any. The trace’s `relatedIfEvaluated=false` at the final CALLGATE is an unevaluated sentinel when holdsAny=true; it is not evidence that a second relation ran.','','### Reachable any distinction','','With exactly the production library-member exemption and no depth cutoff, the stock type-graph traversal visits **1,896** types from the array argument, **1,890** from the assertNode target, and **1,889** from each test signature, finding **zero any types**. Predicate-target graphs are also checked and contain no any. The traversal follows unions/intersections, reference type arguments, properties, call/construct parameter and return types, and index value types; seen types break cycles. Generic type-parameter constraints are not followed, matching the production walker.','','If library members are included, actual any witnesses do exist. These are excluded library method parameters, not the cause of the recorded refusal:']
for call in requested:
 for label,key in [('argument','unrestrictedArgumentGraph'),('test','unrestrictedTestGraph')]:
  witnesses=call[key]['any'];assert witnesses
  lines+=['','- '+call['function']+' '+label+': `'+ ' → '.join(witnesses[0]['path'])+'`.']
lines+=['','The first unrestricted exploratory traversal tried enumerating the entire library graph and stopped at its 100,000-type guard (exit 1); it is retained as `checker-unrestricted-initial.*`. The final script exhaustively traverses the production-exempt graph and records just the first witness when library members are included, avoiding an unbounded expansion of generic library signatures.','','### Full depth paths for the requested calls','','Depth zero is the checked root. Each following row is exactly one recursive edge, including union selections and type arguments. The following four paths are the first matching events for the requested calls; all repetitions are retained in JSON.']
for name,substring in [('assertEachNode','node is ArrayBindingElement'),('assertNode','node is BindingName')]:
 events=[t for t in traces if 'of '+name+' ' in t['parameter'] and substring in t['parameter']]
 for i,t in enumerate(events[:2]):
  lines+=['','#### '+name+(' caller-type recovery guard' if i==0 else ' promised callback-parameter guard'),'','`'+t['parameter']+'`','',table(['Depth','Exact edge and type'],list(enumerate(t['path']))),f"Bound hit: depth **{t['depth']}**, flags **{t['flags']}**, TypeFlagsAny bit **0**."]
lines+=['','## 4. Difference from the small shape','','The callback bodies have the same relevant shape: an unchanged input parameter (or const for-of element), presence tests, and a direct `test(...)` call with that value. The real types add tsc’s large recursive AST graph. `BindingOrAssignmentElement` expands to declaration, binding, assignment and expression variants; their members lead through parent/emitNode/JSDoc/declaration graphs far enough for the depth-first guard to reach 32 before completing. The real assertNode target is a similarly connected union. Neither root itself is any.','','Main’s in-tree small-shape tests use `interface N { readonly kind: number }` and `interface Id extends N { readonly kind: 1; readonly text: string }`. That graph has no tsc parent/emitNode/JSDoc links. Both `TestOverloadCallbackAssertNode` and `TestOverloadCallbackAssertEachNode` pass on this exact main (they lower and agree with Node). The repository’s assertEachNode twin also omits NodeArray-specific overloads and stackCrawlMark; those shape differences are documented in its source, but the observed blocker here is the depth-bound path. Optimizer’s separate small-program source was not supplied, so this comparison names the retained repository twin rather than claiming to inspect that unpublished program.','','This is a diagnosis, not a proposed relaxation: production deliberately treats reaching the bound as unsafe. No optimizer code or adaptation was modified.','','## Reproduction and checks','','See `commands.md`, `measure.sh`, `checker.cjs` and `instrument.py`. All children run through `run.py` with a 1,740-second limit and a ten-second termination grace; each wrapper reports and propagates its own child’s status. All final census, probe, checker, build and small-shape test children exit zero. The exploratory graph-size refusal above is the only retained nonzero child. Go source evidence uses `.go.txt`. No compiler binary or scratch tree is committed.','']
stats=[]
for name in ['census','probe-build','probe','checker','small-shape-tests']:
 d=read(out/(name+'.time.json'));assert d['exit_code']==0 and not d['timed_out'] and d['wall_seconds']<1800
 stats.append([name,round(d['wall_seconds'],3),d['exit_code']])
lines+=[table(['Child','Wall seconds','Own exit'],stats)]
(out/'REPORT.md').write_text('\n'.join(lines).rstrip()+'\n')
validation=dict(main=mainsha,all_747_adapted_hashes_match=True,stock_checker_diagnostics=0,stock_and_probe_streams_equal=True,full_mode_single_file=True,units=len(units),overload_parameter_observations=len(selected),true_walker_events=len(traces),all_true_events_depth_bound_32=True,all_true_events_no_any_bit=True,complete_33_node_paths=True,production_graph_has_no_any=all(not x[k]['any'] for x in c['calls'] for k in ['argumentGraph','testGraph']),all_final_child_exits_zero=True,small_shape_tests_pass=True)
(out/'validation.json').write_text(json.dumps(validation,indent=2)+'\n');print(json.dumps(validation,indent=2))
